    while i < n:
        line = lines[i]
        i += 1
        if line.startswith("#"):
            yield "comment", line
            continue
        if not line.strip():
            continue
        if quoted:
            while line.count('"') % 2 == 1 and i < n:
                line += "\n" + lines[i]
                i += 1
            row = next(csv.reader([line], delimiter=",", quotechar='"'), [])
            yield "row", row
        else:
            yield "row", line.split(YIELD_DELIM[0])


YIELD_DELIM = [","]

DEPOT_COLS = {
    "east": {"id", "type", "shipped", "gross", "net", "status", "note"},
    "lakeside": {"id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"},
    "river": {"t", "ref", "shipped", "weight", "status"},
    "west": {"id", "typ", "shipped", "weight", "status", "note"},
    "harbor": {"rec", "ref", "date", "weight", "state"},
}
DELIM = {"east": ",", "lakeside": ",", "river": "\t", "west": ";", "harbor": "|"}


def parse_delimited(depot, text):
    delim = DELIM[depot]
    YIELD_DELIM[0] = delim
    cols = DEPOT_COLS[depot]
    seq = None
    dirs = {}
    header = None
    out = []
    for kind, item in split_records(lines_of(text), delim == ","):
        if kind == "comment":
            m = re.match(r"#\s*([A-Za-z][A-Za-z ]*?)\s*:\s*(.*?)\s*$", item)
            if m:
                name = re.sub(r"\s+", " ", m.group(1).lower())
                dirs[name] = m.group(2)
                if name == "seq" and seq is None:
                    seq = int(m.group(2))
            m = re.match(r"#harbor export seq=(\d+)", item)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        row = item
        if row and row[-1] == "" and delim != ",":
            pass
        stripped = [f.strip().lower() for f in row]
        if stripped and all(f in cols for f in stripped) and len(stripped) > 1:
            header = stripped
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        extra = row[len(header):]
        idcol = next(c for c in ("id", "ref") if c in header)
        num = parse_id(r.get(idcol, ""))
        if num is None:
            continue  # trailer / total row
        out.append(build_delimited(depot, r, extra, dirs, num))
    return seq, out


def pick_weight_col(r):
    for c in r:
        m = re.match(r"^(gross|weight)(?:_(kg|g|lb|oz))?$", c)
        if m:
            return c, m.group(2)
    return None, None


def build_delimited(depot, r, extra, dirs, num):
    typ = norm_type(r.get("type") or r.get("kind") or r.get("t") or r.get("typ")
                    or r.get("rec"))
    if typ == "void":
        return rec(num, typ)
    wcol, fieldunit = pick_weight_col(r)
    unit = "kg"
    d = dirs.get("unit") if depot == "east" else dirs.get("weight unit")
    if d:
        unit = norm_unit(d.split()[0])
    comma = depot == "west"
    for e in extra:
        if norm_unit(e) in KG:
            unit = norm_unit(e)  # row's own unit beats directive
            break
    if fieldunit:
        unit = fieldunit
    kg = parse_weight(r[wcol], unit, comma)
    if depot == "river":
        form = dirs.get("date format", "MM/DD/YYYY")
    elif depot == "west":
        form = "DD.MM.YYYY"
    elif depot == "harbor":
        form = dirs.get("dates", "iso")
    elif depot == "east":
        form = dirs.get("dates", "YMD")
    else:
        form = dirs.get("dates", "iso")
    ship = r.get("shipped") or r.get("date")
    month = month_of_date(parse_date(ship, form))
    status = r.get("status") or r.get("state")
    if depot == "harbor":
        status = {"dlv": "delivered", "dll": "delivered_late"}.get(
            status.strip().lower(), status)
    return rec(num, typ, month, kg, norm_status(status))


# --------------------------------------------------------------------- XML
def parse_xml(b):
    root = ET.fromstring(b)
    seq = int(root.get("seq")) if root.get("seq") else None
    rootunit = norm_unit(root.get("weight-unit") or "kg")
    out = []
    for el in root.iter("shipment"):
        num = parse_id(el.get("id"))
        if num is None:
            continue
        typ = norm_type(el.get("type"))
        if typ == "void":
            out.append(rec(num, typ))
            continue
        w = el.find("weight")
        unit = norm_unit(w.get("unit")) if w is not None and w.get("unit") else rootunit
        kg = parse_weight(w.text or "", unit)
        sh = el.find("shipped")
        s = sh.text.strip() if sh is not None and sh.text else el.get("shipped")
        month = xml_month(s)
        st = el.find("status")
        out.append(rec(num, typ, month, kg, norm_status(st.text if st is not None else el.get("status"))))
    return seq, out


def xml_month(s):
    s = s.strip()
    m = re.match(r"^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\s+(\d{4})$", s)
    if m:
        return "%04d-%02d" % (int(m.group(3)), MONTHS[m.group(2).lower()])
    if "T" in s or " " in s:
        return month_of_datetime(s.replace(" ", "T", 1))
    return month_of_date(dt.date.fromisoformat(s))


# ------------------------------------------------------------------- JSONL
def parse_jsonl(text):
    seq = None
    out = []
    for line in lines_of(text):
        if not line.strip():
            continue
        v = json.loads(line)
        for o in (v if isinstance(v, list) else [v]):
            if not isinstance(o, dict):
                continue
            if "meta" in o and "id" not in o:
                if seq is None and isinstance(o["meta"], dict) and "seq" in o["meta"]:
                    seq = int(o["meta"]["seq"])
                continue
            num = parse_id(str(o.get("id", "")))
            if num is None:
                continue
            typ = norm_type(o.get("kind"))
            if typ == "void":
                out.append(rec(num, typ))
                continue
            kg = None
            for k, val in o.items():
                m = re.match(r"^weight_(kg|g|lb|oz)$", k)
                if m:
                    kg = parse_weight(str(val), m.group(1))
            if kg is None and "weight" in o:
                kg = parse_weight(str(o["weight"]), norm_unit(o.get("unit") or "kg"))
            out.append(rec(num, typ, month_of_datetime(o["shipped_at"]), kg,
                           norm_status(o.get("status"))))
    return seq, out


# ------------------------------------------------------------- fixed width
LAYOUTS = {
    "FW1": dict(len=42, type=(9, 10), id=(0, 9), shipped=(10, 17), weight=(17, 25),
                status=(25, 26), date="ydoy", unit="g", scale=Decimal(1)),
    "FW2": dict(len=43, type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26),
                status=(26, 27), date="ymd", unit="kg", scale=Decimal("0.01")),
    "FW3": dict(len=41, type=(16, 17), id=(0, 9), shipped=(9, 16), weight=(17, 24),
                status=(24, 25), date="ydoy", unit="lb", scale=Decimal("0.1")),
}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
             "R": "returned", "H": "held"}


def parse_fixed(text):
    seq = None
    layout = None
    out = []
    for line in lines_of(text):
        if line.startswith("#"):
            m = re.match(r"#LAYOUT\s+(\S+)", line)
            if m:
                layout = m.group(1).upper()
            m = re.match(r"#SEQ\s+(\d+)", line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if "\x0c" in line or "SHIPMENT LISTING" in line:
            continue
        if not line.strip():
            continue
        by_len = [k for k, v in LAYOUTS.items() if v["len"] == len(line)]
        if by_len:
            lay = LAYOUTS[by_len[0]]
        elif layout in LAYOUTS and len(line) < LAYOUTS[layout]["len"]:
            lay = LAYOUTS[layout]
            line = line.ljust(lay["len"])
        else:
            warn("unrecognized fixed-width line: %r" % line)
            continue

        def f(name):
            a, b = lay[name]
            return line[a:b]
        num = parse_id(f("id"))
        if num is None:
            continue
        typ = norm_type(f("type"))
        if typ == "void":
            out.append(rec(num, typ))
            continue
        w = Decimal(int(f("weight"))) * lay["scale"] * KG[lay["unit"]]
        s = f("shipped")
        if lay["date"] == "ydoy":
            d = dt.date(int(s[:4]), 1, 1) + dt.timedelta(days=int(s[4:]) - 1)
        else:
            d = dt.date(int(s[:4]), int(s[4:6]), int(s[6:8]))
        out.append(rec(num, typ, month_of_date(d), w,
                       FW_STATUS.get(f("status").strip().upper(), "?")))
    return seq, out


# --------------------------------------------------------------------- main
def parse_file(depot, path):
    b = read_bytes(path)
    if depot == "central":
        return parse_xml(b)
    text = decode(b)
    if depot == "north":
        return parse_jsonl(text)
    if depot == "south":
        return parse_fixed(text)
    return parse_delimited(depot, text)


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0].lower()
        if depot not in ORDER:
            warn("unknown depot file %s" % name)
            continue
        seq, recs = parse_file(depot, path)
        if seq is None:
            warn("no seq in %s" % name)
            seq = 0
        exports.setdefault(depot, []).append((seq, name, recs))

    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        for seq, name, recs in sorted(lst, key=lambda x: (x[0], x[1])):
            for r in recs:
                if r["type"] == "new":
                    if r["num"] in cur:
                        resends += 1
                    else:
                        cur[r["num"]] = r
                elif r["type"] == "correction":
                    cur[r["num"]] = r
                    corrections += 1
                else:
                    cur.pop(r["num"], None)
                    corrections += 1
        current[depot] = cur

    owners = {}
    for depot in ORDER:
        for num in current.get(depot, {}):
            owners.setdefault(num, []).append(depot)
    handovers = sum(1 for v in owners.values() if len(v) > 1)

    depots = {d: [0, Decimal(0)] for d in sorted(exports)}
    months = {}
    for num, ds in owners.items():
        r = current[ds[0]][num]
        if r["status"] not in ("delivered", "delivered_late"):
            continue
        depots[ds[0]][0] += 1
        depots[ds[0]][1] += r["kg"]
        m = months.setdefault(r["month"], [0, Decimal(0)])
        m[0] += 1
        m[1] += r["kg"]

    def fmt(v):
        return {"shipments": v[0],
                "total_kg": float(v[1].quantize(Decimal("0.01"), ROUND_HALF_UP))}
    result = {
        "depots": {d: fmt(v) for d, v in depots.items()},
        "months": {k: fmt(months[k]) for k in sorted(months)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
